// Stock Visualization with D3.js v6
(function() {
    // Color scheme for sectors
    const sectorColors = {
        'Information Technology': '#3498db',
        'Industry': '#e74c3c',
        'Energy': '#f39c12',
        'Financial': '#2ecc71',
        'ETF': '#9b59b6'
    };

    // Sector cluster positions (relative to center)
    const sectorPositions = {
        'Information Technology': { x: -0.25, y: -0.25 },
        'Industry': { x: 0.25, y: -0.25 },
        'Energy': { x: -0.25, y: 0.25 },
        'Financial': { x: 0.25, y: 0.25 },
        'ETF': { x: 0, y: 0 }
    };

    let selectedTicker = null;
    let stockData = [];

    // Format market cap as readable string (e.g., "1.64T")
    function formatMarketCap(value) {
        if (value === null || value === undefined || isNaN(value) || value === '') {
            return 'N/A';
        }
        const num = parseFloat(value);
        if (num >= 1e12) {
            return (num / 1e12).toFixed(2) + 'T';
        } else if (num >= 1e9) {
            return (num / 1e9).toFixed(2) + 'B';
        } else if (num >= 1e6) {
            return (num / 1e6).toFixed(2) + 'M';
        } else {
            return num.toLocaleString();
        }
    }

    // Load and parse CSV data
    d3.csv('data/stock-descriptions.csv').then(function(data) {
        stockData = data.map(d => ({
            ticker: d.ticker,
            name: d['full name'],
            sector: d.sector,
            marketCap: d.marketCap ? parseFloat(d.marketCap) : null,
            country: d.country || null,
            website: d.website || null,
            isETF: d.sector === 'ETF'
        }));

        createBubbleChart(stockData);
        createDataTable(stockData);
        createLegend();
    });

    function createBubbleChart(data) {
        const container = d3.select('#bubble-chart');
        const width = container.node().getBoundingClientRect().width;
        const height = 600;
        const centerX = width / 2;
        const centerY = height / 2;

        const svg = container.append('svg')
            .attr('width', width)
            .attr('height', height);

        // Create tooltip
        const tooltip = d3.select('body').append('div')
            .attr('class', 'tooltip');

        // Scale for bubble radius based on market cap
        const marketCaps = data.filter(d => d.marketCap).map(d => d.marketCap);
        const radiusScale = d3.scaleSqrt()
            .domain([d3.min(marketCaps), d3.max(marketCaps)])
            .range([15, 50]);

        const defaultETFRadius = 18;

        // Create nodes with initial positions
        const nodes = data.map(d => {
            const sectorPos = sectorPositions[d.sector] || { x: 0, y: 0 };
            return {
                ...d,
                radius: d.marketCap ? radiusScale(d.marketCap) : defaultETFRadius,
                x: centerX + sectorPos.x * width * 0.3 + (Math.random() - 0.5) * 50,
                y: centerY + sectorPos.y * height * 0.3 + (Math.random() - 0.5) * 50
            };
        });

        // Force simulation
        const simulation = d3.forceSimulation(nodes)
            .force('x', d3.forceX(d => {
                const sectorPos = sectorPositions[d.sector] || { x: 0, y: 0 };
                return centerX + sectorPos.x * width * 0.35;
            }).strength(0.3))
            .force('y', d3.forceY(d => {
                const sectorPos = sectorPositions[d.sector] || { x: 0, y: 0 };
                return centerY + sectorPos.y * height * 0.35;
            }).strength(0.3))
            .force('collide', d3.forceCollide(d => d.radius + 2).strength(1))
            .force('center', d3.forceCenter(centerX, centerY).strength(0.05));

        // Create bubble groups
        const bubbleGroups = svg.selectAll('.bubble-group')
            .data(nodes)
            .enter()
            .append('g')
            .attr('class', 'bubble-group');

        // Add circles
        const bubbles = bubbleGroups.append('circle')
            .attr('class', 'bubble')
            .attr('r', d => d.radius)
            .attr('fill', d => sectorColors[d.sector] || '#999')
            .attr('data-ticker', d => d.ticker)
            .on('mouseover', function(event, d) {
                if (!d.isETF) {
                    tooltip.classed('visible', true)
                        .html(`
                            <div class="ticker">${d.ticker}</div>
                            <div class="name">${d.name}</div>
                            <div class="sector">${d.sector}</div>
                        `);
                }
            })
            .on('mousemove', function(event, d) {
                if (!d.isETF) {
                    tooltip
                        .style('left', (event.pageX + 15) + 'px')
                        .style('top', (event.pageY - 10) + 'px');
                }
            })
            .on('mouseout', function() {
                tooltip.classed('visible', false);
            })
            .on('click', function(event, d) {
                selectStock(d.ticker);
            });

        // Add labels
        const labels = bubbleGroups.append('text')
            .attr('class', 'bubble-label')
            .text(d => d.ticker)
            .style('font-size', d => Math.min(d.radius * 0.6, 12) + 'px');

        // Update positions on tick
        simulation.on('tick', () => {
            // Keep bubbles within bounds
            nodes.forEach(d => {
                d.x = Math.max(d.radius, Math.min(width - d.radius, d.x));
                d.y = Math.max(d.radius, Math.min(height - d.radius, d.y));
            });

            bubbles
                .attr('cx', d => d.x)
                .attr('cy', d => d.y);

            labels
                .attr('x', d => d.x)
                .attr('y', d => d.y);
        });
    }

    function createDataTable(data) {
        const table = d3.select('#stock-table');
        const tbody = table.select('tbody');

        const rows = tbody.selectAll('tr')
            .data(data)
            .enter()
            .append('tr')
            .attr('data-ticker', d => d.ticker)
            .on('click', function(event, d) {
                selectStock(d.ticker);
            });

        rows.append('td').text(d => d.ticker);
        rows.append('td').text(d => d.name);
        rows.append('td').text(d => d.sector);
        rows.append('td')
            .attr('class', 'market-cap')
            .text(d => formatMarketCap(d.marketCap));
    }

    function createLegend() {
        const legend = d3.select('#legend');

        Object.entries(sectorColors).forEach(([sector, color]) => {
            const item = legend.append('div')
                .attr('class', 'legend-item');

            item.append('div')
                .attr('class', 'legend-color')
                .style('background-color', color);

            item.append('span')
                .text(sector);
        });
    }

    function selectStock(ticker) {
        // Toggle selection if clicking same stock
        if (selectedTicker === ticker) {
            selectedTicker = null;
        } else {
            selectedTicker = ticker;
        }

        // Update bubble selection
        d3.selectAll('.bubble')
            .classed('selected', d => d.ticker === selectedTicker);

        // Update table row selection
        d3.selectAll('#stock-table tbody tr')
            .classed('selected', function() {
                return d3.select(this).attr('data-ticker') === selectedTicker;
            });

        // Scroll table row into view if selected
        if (selectedTicker) {
            const selectedRow = document.querySelector(`#stock-table tr[data-ticker="${selectedTicker}"]`);
            if (selectedRow) {
                selectedRow.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        }
    }
})();

